using ThemeType = ui::ColorProviderKey::ThemeInitializerSupplier::ThemeType;

struct ExpectedThreadsRailColors {
  SkColor bg;
  SkColor primary_font;
  SkColor secondary_font;
  SkColor flyout_bg;
  SkColor surface_container;
  SkColor surface_container_high;
  SkColor primary;
  SkColor tooltip_bg;
  SkColor state_bg;
  SkColor divider;
  SkColor loader_base;
  SkColor loader_highlight;
  SkColor scrollbar_thumb;
};

void ExpectThreadsRailColors(const ui::ColorProvider& provider,
                             const ExpectedThreadsRailColors& expected) {
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailBackground),
            expected.bg);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailPrimaryFont),
            expected.primary_font);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailSecondaryFont),
            expected.secondary_font);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailBrandPrimaryFont),
            expected.primary_font);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailBrandSecondaryFont),
            expected.secondary_font);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailFlyoutMenuBackground),
            expected.flyout_bg);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailContainerBackground),
            color_utils::AlphaBlend(expected.primary_font, expected.bg,
                                    static_cast<SkAlpha>(0.08f * 255)));
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailSurfaceContainer),
            expected.surface_container);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailSurfaceContainerHigh),
            expected.surface_container_high);
  EXPECT_EQ(
      provider.GetColor(kColorNewTabPageThreadsRailSurfaceContainerHighest),
      expected.state_bg);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailPrimary),
            expected.primary);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailTooltipContainer),
            expected.tooltip_bg);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailHoverBackground),
            expected.state_bg);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailMenuOpenBackground),
            expected.state_bg);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailSelectedBackground),
            expected.state_bg);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailDivider),
            expected.divider);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailScrim),
            provider.GetColor(ui::kColorSysStateScrim));
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailLoaderBase),
            expected.loader_base);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailLoaderHighlight),
            expected.loader_highlight);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailScrollbarThumb),
            expected.scrollbar_thumb);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailUpdateDot),
            expected.primary);
}

TEST(NewTabPageColorMixer, LightAndDarkThemeColors) {
  constexpr SkColor kToolbarColors[2] = {SK_ColorWHITE, gfx::kGoogleGrey900};
  for (const SkColor& toolbar_color : kToolbarColors) {
    ui::ColorProvider provider;
    ui::ColorProviderKey key;
    if (color_utils::IsDark(toolbar_color)) {
      key.color_mode = ui::ColorProviderKey::ColorMode::kDark;
    }
    ui::AddColorMixers(&provider, key);
    ui::ColorMixer& mixer = provider.AddMixer();
    mixer[kColorToolbar] = {toolbar_color};
    AddNewTabPageColorMixer(&provider, key);

    EXPECT_EQ(provider.GetColor(kColorToolbar), toolbar_color);
    EXPECT_EQ(provider.GetColor(kColorNewTabPageBackground), toolbar_color);
    EXPECT_EQ(provider.GetColor(kColorNewTabPageButtonBackground),
              toolbar_color);

    if (toolbar_color == SK_ColorWHITE) {
      EXPECT_EQ(provider.GetColor(kColorNewTabPageModuleBackground),
                gfx::kGoogleGrey100);
      ExpectThreadsRailColors(
          provider,
          {
              .bg = gfx::kGoogleGrey100,
              .primary_font = gfx::kGoogleGrey900,
              .secondary_font = gfx::kGoogleGrey700,
              .flyout_bg = provider.GetColor(ui::kColorMenuBackground),
              .surface_container = SK_ColorWHITE,
              .surface_container_high = toolbar_color,
              .primary = provider.GetColor(ui::kColorButtonBackgroundProminent),
              .tooltip_bg = provider.GetColor(ui::kColorPrimaryBackground),
              .state_bg = SkColorSetA(gfx::kGoogleGrey900,
                                      static_cast<SkAlpha>(0.1 * 255)),
              .divider = gfx::kGoogleGrey300,
              .loader_base = gfx::kGoogleGrey200,
              .loader_highlight = gfx::kGoogleGrey050,
              .scrollbar_thumb =
                  provider.GetColor(ui::kColorOverlayScrollbarFill),
          });
    } else {
      EXPECT_EQ(provider.GetColor(kColorNewTabPageModuleBackground),
                gfx::kGoogleGrey800);
      ExpectThreadsRailColors(
          provider,
          {
              .bg = gfx::kGoogleGrey800,
              .primary_font = gfx::kGoogleGrey200,
              .secondary_font = gfx::kGoogleGrey500,
              .flyout_bg = provider.GetColor(ui::kColorMenuBackground),
              .surface_container = gfx::kGoogleGrey900,
              .surface_container_high = toolbar_color,
              .primary = provider.GetColor(ui::kColorButtonBackgroundProminent),
              .tooltip_bg = provider.GetColor(ui::kColorPrimaryBackground),
              .state_bg = SkColorSetA(gfx::kGoogleGrey200,
                                      static_cast<SkAlpha>(0.1 * 255)),
              .divider = gfx::kGoogleGrey700,
              .loader_base = gfx::kGoogleGrey700,
              .loader_highlight = gfx::kGoogleGrey600,
              .scrollbar_thumb =
                  provider.GetColor(ui::kColorOverlayScrollbarFill),
          });
    }

    // Isolated Tab Page colors always remain light.
    EXPECT_EQ(provider.GetColor(kColorIsolatedTabPageBackground),
              SK_ColorWHITE);
    EXPECT_EQ(provider.GetColor(kColorIsolatedTabPageCardBackground),
              SkColorSetRGB(0xF8, 0xFA, 0xFD));
    EXPECT_EQ(provider.GetColor(kColorIsolatedTabPageNoticeBorder),
              gfx::kGoogleBlue100);
    EXPECT_EQ(provider.GetColor(kColorIsolatedTabPageLink),
              gfx::kGoogleBlue600);
    EXPECT_EQ(provider.GetColor(kColorIsolatedTabPageNoticeIcon),
              SK_ColorBLACK);
  }
}

TEST(NewTabPageColorMixer, CustomColorComprehensiveThemeColors) {
  ui::ColorProvider provider;
  ui::ColorProviderKey key;
  key.custom_theme =
      base::WrapRefCounted(new CustomThemeSupplier(ThemeType::kAutogenerated));
  ui::AddColorMixers(&provider, key);
  ui::ColorMixer& mixer = provider.AddMixer();
  mixer[kColorToolbar] = {gfx::kGoogleGreen300};
  AddNewTabPageColorMixer(&provider, key);

  EXPECT_EQ(provider.GetColor(kColorToolbar), gfx::kGoogleGreen300);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageBackground),
            gfx::kGoogleGreen300);
  SkColor contrasting_color = GetContrastingColor(gfx::kGoogleGreen300, 0.1f);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageButtonBackground),
            contrasting_color);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageMostVisitedTileBackground),
            contrasting_color);
  const SkColor expected_primary_font =
      color_utils::GetColorWithMaxContrast(contrasting_color);
  const SkColor expected_secondary_font =
      color_utils::PickGoogleColor(gfx::kGoogleGrey500, contrasting_color,
                                   color_utils::kMinimumReadableContrastRatio);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageThreadsRailSecondaryFont),
            provider.GetColor(kColorNewTabPageSecondaryForeground));
  const SkColor expected_primary = color_utils::PickGoogleColor(
      provider.GetColor(ui::kColorButtonBackgroundProminent), contrasting_color,
      color_utils::kMinimumVisibleContrastRatio);
  ExpectThreadsRailColors(
      provider,
      {
          .bg = contrasting_color,
          .primary_font = expected_primary_font,
          .secondary_font = expected_secondary_font,
          .flyout_bg = SK_ColorWHITE,
          .surface_container = SK_ColorWHITE,
          .surface_container_high = gfx::kGoogleGrey100,
          .primary = expected_primary,
          .tooltip_bg = SK_ColorWHITE,
          .state_bg = SkColorSetA(gfx::kGoogleGrey900,
                                  static_cast<SkAlpha>(0.1f * 255)),
          .divider = gfx::kGoogleGrey300,
          .loader_base = gfx::kGoogleGrey200,
          .loader_highlight = gfx::kGoogleGrey050,
          .scrollbar_thumb = SkColorSetA(expected_primary_font,
                                         static_cast<SkAlpha>(0.6f * 255)),
      });
}

TEST(NewTabPageColorMixer, CustomExtensionThemeThreadsRailColors) {
  ui::ColorProvider provider;
  ui::ColorProviderKey key;
  key.custom_theme =
      base::WrapRefCounted(new CustomThemeSupplier(ThemeType::kExtension));
  ui::AddColorMixers(&provider, key);
  ui::ColorMixer& mixer = provider.AddMixer();
  mixer[kColorToolbar] = {gfx::kGoogleBlue900};
  AddNewTabPageColorMixer(&provider, key);

  SkColor contrasting_color = GetContrastingColor(gfx::kGoogleBlue900, 0.2f);
  const SkColor expected_primary_font =
      color_utils::GetColorWithMaxContrast(contrasting_color);
  const SkColor expected_secondary_font =
      color_utils::PickGoogleColor(gfx::kGoogleGrey700, contrasting_color,
                                   color_utils::kMinimumReadableContrastRatio);
  const SkColor expected_primary = color_utils::PickGoogleColor(
      provider.GetColor(ui::kColorButtonBackgroundProminent), contrasting_color,
      color_utils::kMinimumVisibleContrastRatio);
  EXPECT_GE(color_utils::GetContrastRatio(expected_primary, contrasting_color),
            color_utils::kMinimumVisibleContrastRatio);
  ExpectThreadsRailColors(
      provider,
      {
          .bg = contrasting_color,
          .primary_font = expected_primary_font,
          .secondary_font = expected_secondary_font,
          .flyout_bg = gfx::kGoogleGrey900,
          .surface_container = gfx::kGoogleGrey900,
          .surface_container_high = gfx::kGoogleGrey800,
          .primary = expected_primary,
          .tooltip_bg = gfx::kGoogleGrey900,
          .state_bg =
              SkColorSetA(SK_ColorWHITE, static_cast<SkAlpha>(0.1f * 255)),
          .divider = gfx::kGoogleGrey700,
          .loader_base = gfx::kGoogleGrey700,
          .loader_highlight = gfx::kGoogleGrey600,
          .scrollbar_thumb = SkColorSetA(expected_primary_font,
                                         static_cast<SkAlpha>(0.6f * 255)),
      });
}

TEST(NewTabPageColorMixer, DefaultColorComprehensiveThemeColor) {
  constexpr SkColor kSampleToolbarColor = SK_ColorWHITE;
  ui::ColorProvider provider;
  ui::ColorMixer& mixer = provider.AddMixer();
  mixer[kColorToolbar] = {kSampleToolbarColor};
  mixer[ui::kColorFrameActive] = {SK_ColorBLUE};
  ui::ColorProviderKey key;
  key.custom_theme =
      base::WrapRefCounted(new CustomThemeSupplier(ThemeType::kAutogenerated));
  AddNewTabPageColorMixer(&provider, key);

  EXPECT_EQ(provider.GetColor(kColorToolbar), kSampleToolbarColor);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageBackground), kSampleToolbarColor);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageButtonBackground),
            kSampleToolbarColor);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageButtonForeground),
            gfx::kGoogleBlue600);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageLink), gfx::kGoogleBlue600);
  EXPECT_EQ(provider.GetColor(kColorNewTabPageMostVisitedTileBackground),
            gfx::kGoogleGrey100);
}

